cases = [['A05', 'disabled', 'const LIMB_PICKER_ENABLED = true;', 'const LIMB_PICKER_ENABLED = false;'], ['A05', 'no-css', '/* PART H PHASE 15.1.5 — Release 15a A05: Missing Limb\'s select as a shared field (FT-12, ruling Q1).\n   The label\'s word (span.lp15-label, "Missing limb") sits above the select as every field label does, and keeps the\n   sheet\'s shared label style. The select takes the shared field\'s font, padding, border, radius and colour, with a\n   44 px touch height; the note follows below it with the shared 6 px helper gap. The row\'s other controls are\n   unaffected: these rules match only a row this unit has marked (lp15-row, lp15-field), so Lost Love, Contrary and the\n   rest keep Phase 4.5.31\'s (Part I) layout. The ID in each selector outranks the carousel\'s own label rule.\n   Waits for body.lp15-on, which this unit\'s switch sets. */\nhtml body.lp15-on #disadvList .chk4531-row.lp15-row {\n  display: block;\n}\nhtml body.lp15-on #disadvList label.chk4531-field.lp15-field {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 0;\n  margin: 0;\n}\nhtml body.lp15-on #disadvList label.lp15-field .lp15-label {\n  display: block;\n  margin-bottom: 4px;\n}\nhtml body.lp15-on #disadvList label.lp15-field select.chk4531-limb {\n  min-width: 200px;\n  max-width: 100%;\n  min-height: 44px;\n  margin: 0;\n  padding: 7px 9px;\n  font-family: \'EB Garamond\', serif;\n  font-size: 1rem;\n  letter-spacing: normal;\n  text-transform: none;\n  color: var(--ink);\n  background: #fffdf8;\n  border: 1px solid var(--line);\n  border-radius: 5px;\n}\nhtml body.lp15-on #disadvList .chk4531-row.lp15-row > .chk4531-note {\n  display: block;\n  margin-top: 6px;\n  line-height: 1.5;\n}\n', ''], ['A06', 'disabled', 'const GRANT_ACTIONS_ENABLED = true;', 'const GRANT_ACTIONS_ENABLED = false;'], ['A06', 'no-css', "/* PART H PHASE 15.1.6 — Release 15a A06: grant actions as one compact group, with the state beside it (FT-42, ruling Q1).\n   Matches only a grant box that is offering an action (it has buttons): Zakyo Toshi Citizen's .supp4540-koku and\n   Wealthy's .wealth4517-status. The explanation line takes the full width; below it the two actions sit with a 10 px\n   gap, 44 px tall; the first is the primary (filled in ink), the second stays outlined. The state follows them as\n   generated text, so no phase's own text or element changes. A recorded box has no buttons and is left as it is.\n   Hover keeps full opacity: the global button:hover fade sticks after a tap on a phone (A15's lesson).\n   Waits for body.ga15-on, which this unit's switch sets. */\nhtml body.ga15-on #advList .supp4540-koku:has(> button),\nhtml body.ga15-on #advList .wealth4517-status:has(> button) {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 10px;\n}\nhtml body.ga15-on #advList .supp4540-koku:has(> button) > span,\nhtml body.ga15-on #advList .wealth4517-status:has(> button) > span {\n  flex: 1 1 100%;\n  min-width: 0;\n}\nhtml body.ga15-on #advList .supp4540-koku > button,\nhtml body.ga15-on #advList .wealth4517-status > button {\n  min-height: 44px;\n  margin: 0;\n  padding: 0 16px;\n}\nhtml body.ga15-on #advList .supp4540-koku > button:first-of-type,\nhtml body.ga15-on #advList .wealth4517-status > button:first-of-type {\n  background: var(--ink);\n  border-color: var(--ink);\n  color: var(--paper);\n}\nhtml body.ga15-on #advList .supp4540-koku > button:hover,\nhtml body.ga15-on #advList .wealth4517-status > button:hover {\n  opacity: 1;\n}\nhtml body.ga15-on #advList .wealth4517-status > button:disabled {\n  opacity: .5;\n}\nhtml body.ga15-on #advList .supp4540-koku:has(> button)::after,\nhtml body.ga15-on #advList .wealth4517-status:has(> button)::after {\n  content: 'Not recorded yet';\n  font-size: .85rem;\n  font-style: italic;\n  color: var(--ink-soft);\n}\nhtml body.ga15-on #advList .wealth4517-status.wealth4517-excess:has(> button)::after {\n  content: 'Not settled yet';\n}\n", ''], ['A07', 'disabled', 'const MOON_ROW_ENABLED = true;', 'const MOON_ROW_ENABLED = false;'], ['A07', 'no-css', '/* PART H PHASE 15.1.7 — Release 15a A07: the Moon row (ruling Q1).\n   Matches only Lord Moon\'s Curse\'s row: the configuration row that holds the Lord Moon fix\'s (LM7) .lm7-moon box. The severity\n   summary gains a "Severity" label in the sheet\'s shared label style (generated text, so the summary\'s own text is\n   unchanged). The moon box becomes a column on the row\'s left edge: the full-moon tick on its own 44 px line, a 22 px box\n   in body text (not the carousel\'s tiny capitals), then the resist button at 44 px. The ID in each selector outranks the\n   carousel\'s label rule and the fix\'s own injected style.\n   Waits for body.mr15-on, which this unit\'s switch sets. */\nhtml body.mr15-on #disadvList .adv-config-row:has(> .lm7-moon) > .adv-config-summary::before {\n  content: \'Severity\';\n  margin-right: 8px;\n  font-family: \'Noto Sans JP\', sans-serif;\n  font-size: .66rem;\n  letter-spacing: .09em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\nhtml body.mr15-on #disadvList .lm7-moon {\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 8px;\n  margin-top: 8px;\n}\nhtml body.mr15-on #disadvList label.lm7-tick {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 44px;\n  margin: 0;\n  padding: 0;\n  font-family: \'EB Garamond\', serif;\n  font-size: .95rem;\n  letter-spacing: normal;\n  text-transform: none;\n  color: var(--ink);\n}\nhtml body.mr15-on #disadvList label.lm7-tick input {\n  flex: none;\n  width: 22px;\n  height: 22px;\n  margin: 0;\n}\nhtml body.mr15-on #disadvList .lm7-roll {\n  min-height: 44px;\n  margin: 0;\n}\n', ''], ['A11', 'disabled', 'const TEXT_EDGES_ENABLED = true;', 'const TEXT_EDGES_ENABLED = false;'], ['A11', 'no-css', "/* PART H PHASE 15.1.11 — Release 15a A11: explanatory text gaps and one left edge (FT-51, ruling Q1, owner's additions).\n   1. In Play, a card's locked name and description show as plain text (Phase 12 (Part K) makes their border\n      transparent); without their horizontal padding and border they start on the card's text edge, with the lines\n      between them. Manage keeps the editable boxes as they are.\n   2. Insight's and Spent XP's notes: the shared 6 px helper gap on a laptop, where their inline style pulled them 4 px\n      up (the carousel's own phone rule already gives 14 px, or 10 px on very small screens), and a 1.5 line height.\n   3. The six condition rows' controls (Phase 4.5.31 and Phase 4.5.32, Part I) keep a 6 px gap above the description.\n   Waits for body.te15-on, which this unit's switch sets. */\nhtml body.te15-on.pm12-play #advList .entry .en-name[data-pm12-locked],\nhtml body.te15-on.pm12-play #disadvList .entry .en-name[data-pm12-locked],\nhtml body.te15-on.pm12-play #advList .entry .en-desc[data-pm12-locked],\nhtml body.te15-on.pm12-play #disadvList .entry .en-desc[data-pm12-locked] {\n  padding-left: 0;\n  padding-right: 0;\n  border-left-width: 0;\n  border-right-width: 0;\n}\nhtml body.te15-on .section > .grid:has(#f_insightBonus) + .hint,\nhtml body.te15-on .section > .grid:has(#f_xpSpent) + .hint {\n  line-height: 1.5;\n}\n@media (min-width: 769px) {\n  html body.te15-on .section > .grid:has(#f_insightBonus) + .hint,\n  html body.te15-on .section > .grid:has(#f_xpSpent) + .hint {\n    margin-top: 6px !important;\n  }\n}\nhtml body.te15-on #disadvList .chk4531-row,\nhtml body.te15-on #advList .chk4531-row,\nhtml body.te15-on #disadvList .dsx4532-row,\nhtml body.te15-on #advList .dsx4532-row {\n  margin-bottom: 6px;\n}\n", ''], ['A04.1', 'disabled', 'const INLINE_RULES_ENABLED = true;', 'const INLINE_RULES_ENABLED = false;'], ['A04.1', 'no-css', '/* PART H PHASE 15.1.4.1 — Release 15a A04.1: each option\'s rule inline, in Paragon\'s option card (owner, 7 November).\n   Matches only an option this unit has marked (ir15-item, ir15-opt). The option becomes Paragon\'s card: a 1 px line\n   border, 6 px radius, 4 x 6 px padding, left-aligned .9 rem text at 1.35, the radio beside the first line; the name,\n   price and rule run on as one paragraph. Its "Rule" disclosure and Phase 4.54\'s (Part I) i on the option are not\n   drawn: the rule is on the card itself. Every other control in the window, and the row\'s i after choosing, is\n   unaffected. The ID in each selector outranks the pickers\' own option rules and the carousel\'s label rule.\n   Waits for body.ir15-on, which this unit\'s switch sets. */\nhtml body.ir15-on #advConfigGrid .ir15-item {\n  display: block;\n  width: 100%;\n  max-width: none;\n  min-width: 0;\n  height: auto;\n  min-height: 32px;\n  box-sizing: border-box;\n  margin: 0;\n  padding: 4px 6px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  background: transparent;\n  text-align: start;\n}\nhtml body.ir15-on #advConfigGrid label.ir15-opt {\n  display: block;\n  position: relative;\n  width: auto;\n  margin: 0;\n  padding: 0 0 0 21px;\n  /* One box per option (owner\'s review, 7 November): Phase 4.5.21\'s own option card border is not drawn inside it. */\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  font-family: \'Noto Sans JP\', sans-serif;\n  font-size: .9rem;\n  line-height: 1.35;\n  letter-spacing: normal;\n  text-transform: none;\n  text-align: start;\n  white-space: normal;\n  color: var(--ink);\n  cursor: pointer;\n}\nhtml body.ir15-on #advConfigGrid label.ir15-opt > input {\n  position: absolute;\n  left: 0;\n  top: 3px;\n  width: 13px;\n  height: 13px;\n  margin: 0;\n}\nhtml body.ir15-on #advConfigGrid label.ir15-opt > span {\n  display: inline;\n  overflow-wrap: break-word;\n}\nhtml body.ir15-on #advConfigGrid .ir15-item > details,\nhtml body.ir15-on #advConfigGrid .ir15-item .adv-config-info {\n  display: none !important;\n}\n', ''], ['A05', 'wrong-label', "api.LABEL = 'Missing limb';", "api.LABEL = 'Missing';"], ['A05', 'short-select', 'html body.lp15-on #disadvList label.lp15-field select.chk4531-limb {\n  min-width: 200px;\n  max-width: 100%;\n  min-height: 44px;', 'html body.lp15-on #disadvList label.lp15-field select.chk4531-limb {\n  min-width: 200px;\n  max-width: 100%;\n  min-height: 30px;'], ['A06', 'wrong-state', "  content: 'Not recorded yet';", "  content: 'Pending';"], ['A06', 'unfilled-primary', 'html body.ga15-on #advList .wealth4517-status > button:first-of-type {\n  background: var(--ink);', 'html body.ga15-on #advList .wealth4517-status > button:first-of-type {\n  background: transparent;'], ['A07', 'wrong-severity', "  content: 'Severity';", "  content: 'Level';"], ['A07', 'small-checkbox', 'html body.mr15-on #disadvList label.lm7-tick input {\n  flex: none;\n  width: 22px;\n  height: 22px;', 'html body.mr15-on #disadvList label.lm7-tick input {\n  flex: none;\n  width: 13px;\n  height: 13px;'], ['A11', 'cramped-conditions', 'html body.te15-on #advList .dsx4532-row {\n  margin-bottom: 6px;', 'html body.te15-on #advList .dsx4532-row {\n  margin-bottom: 2px;'], ['A11', 'tight-hint-lines', 'html body.te15-on .section > .grid:has(#f_xpSpent) + .hint {\n  line-height: 1.5;', 'html body.te15-on .section > .grid:has(#f_xpSpent) + .hint {\n  line-height: 1.2;'], ['A04.1', 'truncated-rule', 'span.textContent = api.separator(text) + rule;', 'span.textContent = api.separator(text) + rule.slice(0, -1);'], ['A04.1', 'nested-border', "  /* One box per option (owner's review, 7 November): Phase 4.5.21's own option card border is not drawn inside it. */\n  border: 0;", "  /* One box per option (owner's review, 7 November): Phase 4.5.21's own option card border is not drawn inside it. */\n  border: 1px solid var(--line);"]]


report = {'checked_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'cases': []}
out = Q / (('variants-discover-' if DISCOVER else 'negative-') + hashlib.sha256(original.encode('utf-8')).hexdigest()[:8] + ('-2' if ONLY else ''))


def run(unit, label, body):
    key = unit + ':' + label
    with tempfile.TemporaryDirectory(prefix='l5r-g2-negative-') as folder:
        page = Path(folder) / 'index.html'
        page.write_bytes(body.encode('utf-8'))
        harness = HARNESS[unit]
        r = subprocess.run([NODE, '--require', str(NAVIGATION_BUDGET), '--require', str(SPLASH_FAST), str(harness), str(page)], cwd=str(harness.parent),
                           capture_output=True, text=True, encoding='utf-8', timeout=1800)
    text = r.stdout + r.stderr
    (out / (unit + '-' + label + '.log')).write_bytes(text.encode('utf-8'))
    failed = sorted(re.findall(r'^FAIL (\S+)', text, re.M))
    counts = re.findall(r'(\d+)/(\d+) checks passed', text)
    got = list(map(int, counts[-1])) if counts else []
    case = {'id': key, 'expected_failures': PINNED.get(key), 'actual_failures': failed, 'counts': got, 'exit': r.returncode}
    report['cases'].append(case)
    (out / 'summary.json').write_bytes((json.dumps(report, indent=2) + '\n').encode())
    if DISCOVER:
        exp = sorted(PINNED.get(key) or [])
        print(key + (' MATCH ' if failed == exp else ' DIFF ') + json.dumps({'extra': sorted(set(failed) - set(exp)), 'missing': sorted(set(exp) - set(failed))}) + ' ' + str(got), flush=True)
        return
    assert r.returncode == 1 and failed == sorted(PINNED[key]) and len(got) == 2 and got[1] - got[0] == len(failed), case
    print(key + ': failed exactly its ' + str(len(failed)) + ' pinned checks', flush=True)


for unit, label, old, new in cases:
    assert original.count(old) == 1, (unit, label, 'mutation is not unique', original.count(old))
keys = [u + ':' + l for u, l, _, _ in cases]
assert len(set(keys)) == len(keys) and len({(c[2], c[3]) for c in cases}) == len(cases), 'cases not unique'
assert set(PINNED) == {u + ':baseline' for u in HARNESS} | set(keys), 'every case needs a pin'
print(f'{len(cases)} mutations unique.', flush=True)
if '--dry-run' in sys.argv:
    sys.exit(0)
out.mkdir(exist_ok=True)
baseline = subprocess.check_output(['git', 'show', BASELINE_REF + ':' + P.relative_to(V.parent).as_posix() + '/l5r-character-sheet.html'],
                                   cwd=V.parent).decode('utf-8')
assert hashlib.sha256(baseline.encode('utf-8')).hexdigest() == BASELINE_SHA
for unit in HARNESS:
    if wanted(unit, 'baseline'): run(unit, 'baseline', baseline)
for unit, label, old, new in cases:
    if wanted(unit, label): run(unit, label, original.replace(old, new))
report['passed'] = not DISCOVER
(out / 'summary.json').write_bytes((json.dumps(report, indent=2) + '\n').encode())
print('All ' + str(len(cases) + len(HARNESS)) + ' negative variants matched their pinned failures.' if not DISCOVER else 'Discovery done.')
